#pragma once
#include <cuda_runtime.h>

namespace mla {

constexpr int HEADS = 16;
constexpr int DCKV = 512;

struct Plan {
    int chunk;  // tokens handled by one work item
    int nblk;   // upper bound on the number of token chunks (workspace sizing)
};

// Derived from host-visible shape info only (no device sync).
Plan make_plan(int batch, int total_kv);

void launch(const void* q_nope, const void* q_pe, const void* ckv, const void* kpe,
            const int* kv_indptr, const int* kv_indices, void* p_o, float* p_m,
            float* p_l, unsigned int* sync, void* output, float* lse, int batch,
            const Plan& plan, float sm_scale, cudaStream_t stream);

}  // namespace mla

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/cuda/EmptyTensor.h>
#include <pybind11/stl.h>
#include <tuple>
#include "kernel.h"

std::tuple<torch::Tensor, torch::Tensor> run_dict(
    torch::Tensor q_nope,
    torch::Tensor q_pe,
    torch::Tensor ckv_cache,
    torch::Tensor kpe_cache,
    torch::Tensor kv_indptr,
    torch::Tensor kv_indices,
    float sm_scale
) {
    // Every ATen call on this path costs roughly a microsecond of dispatch, and the
    // per-call floor is what the geomean is made of, so each one is taken only when
    // it would actually do something. Tensor::contiguous() is an inline no-op when
    // the tensor already is contiguous, but Tensor::to() still dispatches.
    if (!q_nope.is_contiguous()) q_nope = q_nope.contiguous();
    if (!q_pe.is_contiguous()) q_pe = q_pe.contiguous();
    if (!ckv_cache.is_contiguous()) ckv_cache = ckv_cache.contiguous();
    if (!kpe_cache.is_contiguous()) kpe_cache = kpe_cache.contiguous();
    if (!kv_indptr.is_contiguous()) kv_indptr = kv_indptr.contiguous();
    if (!kv_indices.is_contiguous()) kv_indices = kv_indices.contiguous();

    int batch_size = q_nope.size(0);
    int num_heads = q_nope.size(1);
    int head_dim = q_nope.size(2);

    auto options = q_nope.options();
    // at::detail::empty_cuda goes straight to the caching allocator; torch::empty
    // would route the same call through the ATen dispatcher first, and on a ~31us
    // per-call floor that dispatch is worth measuring.
    const auto dev = q_nope.device();
    auto output = at::detail::empty_cuda({batch_size, num_heads, head_dim},
                                         q_nope.scalar_type(), dev, c10::nullopt);
    auto lse = at::detail::empty_cuda({batch_size, num_heads}, torch::kFloat32, dev,
                                      c10::nullopt);

    torch::Tensor ip_tmp, ix_tmp;
    if (kv_indptr.scalar_type() != torch::kInt) ip_tmp = kv_indptr.to(torch::kInt);
    if (kv_indices.scalar_type() != torch::kInt) ix_tmp = kv_indices.to(torch::kInt);
    const torch::Tensor& kv_indptr_i32 = ip_tmp.defined() ? ip_tmp : kv_indptr;
    const torch::Tensor& kv_indices_i32 = ix_tmp.defined() ? ix_tmp : kv_indices;

    if (batch_size > 0) {
        int total_kv = (int)kv_indices_i32.size(0);
        mla::Plan plan = mla::make_plan(batch_size, total_kv);

        // One workspace allocation: [o | m | l | cum | map] packed back to back.
        int64_t n_om = (int64_t)plan.nblk * mla::HEADS;
        // Partial output is bf16 (two per float slot); m/l stay fp32. The scratch
        // buffer is cached across calls: allocating it was ~2us of the per-call floor,
        // and it is only ever touched by these two kernels on this stream.
        static torch::Tensor ws;
        int64_t need = n_om * (mla::DCKV / 2 + 2);
        if (!ws.defined() || ws.numel() < need || ws.device() != q_nope.device()) {
            ws = torch::empty({need}, options.dtype(torch::kFloat32));
        }
        float* base = ws.data_ptr<float>();
        void* p_o = base;
        float* p_m = base + n_om * (mla::DCKV / 2);
        float* p_l = p_m + n_om;

        // Grid-barrier state: [arrival counter, generation]. Zeroed once; the
        // counter is self-resetting and the generation is monotone, so no per-call
        // memset sits on the critical path.
        static torch::Tensor sync;
        if (!sync.defined() || sync.device() != q_nope.device()) {
            sync = torch::zeros({2}, options.dtype(torch::kInt32));
        }

        mla::launch(q_nope.data_ptr(), q_pe.data_ptr(), ckv_cache.data_ptr(),
                    kpe_cache.data_ptr(), kv_indptr_i32.data_ptr<int>(),
                    kv_indices_i32.data_ptr<int>(), p_o, p_m, p_l,
                    reinterpret_cast<unsigned int*>(sync.data_ptr<int>()),
                    output.data_ptr(), lse.data_ptr<float>(), batch_size, plan, sm_scale,
                    at::cuda::getCurrentCUDAStream());
    }

    return std::make_tuple(output, lse);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run_dict, "MLA Decode Kernel",
          py::arg("q_nope"), py::arg("q_pe"), 
          py::arg("ckv_cache"), py::arg("kpe_cache"), 
          py::arg("kv_indptr"), py::arg("kv_indices"), 
          py::arg("sm_scale"));
}
